<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/music-library-duplicates.php';
function edit_ok(bool $v):void{if(!$v)throw new RuntimeException('Edit assertion failed');}
function edit_no(callable $f):void{try{$f();}catch(Throwable){return;}throw new RuntimeException('Expected edit denial');}
$dir=sys_get_temp_dir().'/rr-edit-'.bin2hex(random_bytes(6));mkdir($dir,0700);$dir=realpath($dir);$root=$dir.'/media/music';$u=['role'=>'producer','id'=>'test'];
try{$bytes=str_repeat(hex2bin('fffb9000').str_repeat("\0",413),100);$file=$dir.'/test.mp3';file_put_contents($file,$bytes);$r=music_library_upload(['name'=>'Test.mp3','tmp_name'=>$file,'size'=>strlen($bytes),'error'=>0],$u,'c','c',$root,fn()=>true,fn($a,$b)=>copy($a,$b));$t=music_library_prepare($r['track']['id'],$r['track']['sha256'],0,$u,'c','c',$root);$id=$t['id'];$sha=$t['sha256'];$before=file_get_contents($root.'/library.json');$input=['title'=>'Rettet låt','artist'=>'Testartist','album'=>'Testalbum','genre'=>'Country','year'=>'2013','tags'=>'Varm, Ettermiddag, Varm'];
 edit_no(fn()=>music_library_edit($id,$sha,1,$input,['role'=>'observer'],'c','c',$root));edit_no(fn()=>music_library_edit($id,$sha,1,$input,$u,'bad','c',$root));edit_no(fn()=>music_library_edit($id,$sha,0,$input,$u,'c','c',$root));edit_no(fn()=>music_library_edit($id,$sha,1,$input+['unknown'=>'x'],['role'=>'observer'],'c','c',$root));edit_ok(file_get_contents($root.'/library.json')===$before);
 $saved=music_library_edit($id,$sha,1,$input,$u,'c','c',$root);edit_ok(music_library_effective_fields($saved)['title']==='Rettet låt'&&$saved['tags']===['Varm','Ettermiddag']&&$saved['metadata']===$t['metadata']&&$saved['autoTags']===$t['autoTags']&&$saved['revision']===2);edit_ok(hash_file('sha256',$root.'/originals/'.$id.'.mp3')===$sha);
 $before=file_get_contents($root.'/library.json');$bad=$input;$bad['tags']=str_repeat('x',81);edit_no(fn()=>music_library_edit($id,$sha,2,$bad,$u,'c','c',$root));edit_ok(file_get_contents($root.'/library.json')===$before);
 $other=$saved;$other['id']=str_repeat('b',32);$other['sha256']=str_repeat('c',64);$other['metadata']['sourceSha256']=$other['sha256'];edit_ok(count(music_library_possible_duplicates($saved,[$saved,$other]))===1);$other['metadata']['durationSeconds']+=10;edit_ok(music_library_possible_duplicates($saved,[$other])===[]);$other['manualOverrides']['title']='En annen utgave';edit_ok(music_library_possible_duplicates($saved,[$other])===[]);
 $empty=music_library_edit($id,$sha,2,[],$u,'c','c',$root);edit_ok($empty['tags']===[]&&$empty['manualOverrides']===[]&&$empty['metadata']===$t['metadata']);
 $raw='{"energy":"moderat","periods":["Ettermiddag"],"tags":["Varm","Ettermiddag"],"reason":"Forslag","confidence":"medium"}';edit_ok(music_library_producer_result($raw)['tags']===['Varm','Ettermiddag']);edit_no(fn()=>music_library_producer_result(str_replace('Varm','Oppdiktet fakta-tag',$raw)));
 echo "PASS metadata/tag edit: role/CSRF/revision, original/source preservation, clear override, possible duplicate and producer tag validation\n";
}finally{foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST)as$f)$f->isDir()?rmdir($f->getPathname()):unlink($f->getPathname());rmdir($dir);}
